// Ready-made circuits for the free-build mode: some work, some are classic mistakes. Each one explains itself.
import { isHoleRef } from './circuit.js';

export function EXAMPLES(boardKind) {
  if (boardKind === 'esp32') return EXAMPLES_E32();
  const pi = boardKind === 'pi4', u3 = boardKind === 'uno3';
  const P = pi
    ? { sig: 'p11', btn: 'p13', gnd: 'p9', v3: 'p1', v5: 'p2', bad5: 'p13', name: 'GPIO17 (pin 11)' }
    : { sig: 'D5', btn: 'D2', gnd: 'GND2', v3: '3V3', v5: '5V', bad5: 'D3', an: 'A0', name: 'D5' };
  P.dhtV = pi ? 'p1' : u3 ? '5V' : '3V3'; P.dhtPin = pi ? 'p7' : 'D2'; 
  P.joyV = u3 ? '5V' : '3V3'; P.encV = pi ? 'p1' : u3 ? '5V' : '3V3';
  P.rgb = pi ? ['p12', 'p32', 'p33'] : ['D5', 'D6', 'D9'];
  P.rgbGnd = pi ? 'p34' : P.gnd;   // Pi: GND (physical pin 34) next to the PWM pins
  const sig8 = pi ? 'p11' : 'D8';
  const w = (id, from, to, color) => ({ id, type: pi && !isHoleRef(from) ? 'fwire' : 'wire', from, to, color, lift: isHoleRef(from) && isHoleRef(to) ? 12 : 26 });
  const led = (id, anode, cathode, color = 'red') => ({ id, type: 'led', anode, cathode, color });
  const res = (id, a, b, ohms) => ({ id, type: 'resistor', a, b, ohms });
  const ledCircuit = (flip, ohms = 220) => [w('w1', P.sig, 'a10', 'yellow'), res('r1', 'b10', 'b14', ohms), flip ? led('led1', 'c15', 'c14') : led('led1', 'c14', 'c15'), w('w2', P.gnd, 'd15', 'black')];
  const relayPin = pi ? 'p11' : 'D4';
  const ld = (id, from, to, color) => ({ id, type: 'lead', from, to, color, lift: 14 });
  const relayWires = pi
    ? [ld('ld1', 'rel1.DCP', 'a10', 'red'), ld('ld2', 'rel1.DCN', 'a11', 'black'), ld('ld3', 'rel1.IN', 'a12', 'yellow'), w('w1', 'p2', 'b10', 'red'), w('w2', 'p9', 'b11', 'black'), w('w3', 'p11', 'b12', 'yellow'), ld('ld4', 'bat1.POS', 'rel1.COM', 'red'), ld('ld5', 'rel1.NO', 'lamp1.L1', 'orange'), ld('ld6', 'lamp1.L2', 'bat1.NEG', 'black')]
    : [ld('ld1', 'rel1.DCP', '5V', 'red'), ld('ld2', 'rel1.DCN', 'GND3', 'black'), ld('ld3', 'rel1.IN', 'D4', 'yellow'), ld('ld4', 'bat1.POS', 'rel1.COM', 'red'), ld('ld5', 'rel1.NO', 'lamp1.L1', 'orange'), ld('ld6', 'lamp1.L2', 'bat1.NEG', 'black')];
  P.neoVcc = pi ? 'p2' : '5V'; P.neoDin = pi ? 'p12' : 'D6'; P.neoGnd = pi ? 'p6' : P.gnd;
  const neoParts = (vcc, din, gnd) => (pi
    ? [{ id: 'neo1', type: 'neopixel' }, ld('ld1', 'neo1.VCC', 'a10', 'red'), ld('ld2', 'neo1.DIN', 'a11', 'yellow'), ld('ld3', 'neo1.GND', 'a12', 'black'), w('w1', vcc, 'b10', 'red'), w('w2', din, 'b11', 'yellow'), w('w3', gnd, 'b12', 'black')]
    : [{ id: 'neo1', type: 'neopixel' }, ld('ld1', 'neo1.VCC', vcc, 'red'), ld('ld2', 'neo1.DIN', din, 'yellow'), ld('ld3', 'neo1.GND', gnd, 'black')]);
  P.i2cV5 = pi ? 'p2' : '5V'; P.i2cV3 = pi ? 'p1' : '3V3'; P.sda = pi ? 'p3' : u3 ? 'A4' : 'D20'; P.scl = pi ? 'p5' : u3 ? 'A5' : 'D21';
  // a display module standing on the desk: its 4 pins go to breadboard holes a10..a13, the board pins to b10..b13 (pin order of the module: GND, VCC, then SDA/SCL as printed)
  const i2cDisp = (type, id, vcc, sdaPin, sclPin) => {
    const order = type === 'lcd1602' ? ['GND', 'VCC', 'SDA', 'SCL'] : ['GND', 'VCC', 'SCL', 'SDA'], pinFor = { GND: P.gnd, VCC: vcc, SDA: sdaPin, SCL: sclPin }, colour = { GND: 'black', VCC: 'red', SDA: 'blue', SCL: 'yellow' };
    return [{ id, type }, ...order.map((n, i) => ({ id: 'm' + (i + 1), type: 'fwire', from: id + '.' + n, to: 'a' + (10 + i), color: colour[n], lift: 16 })), ...order.map((n, i) => w('w' + (i + 1), pinFor[n], 'b' + (10 + i), colour[n]))];
  };
  // PN2222A low-side switch for a 6 V lamp: the base resistor (ohms, 0 = none) from the pin, emitter column joined to GND and to the battery minus
  const qLamp = (pin, ohms, flip, diode) => [
    { id: 'q1', type: 'npn', row: 'e', col: 10, flip: !!flip },
    ...(ohms ? [res('r1', 'a11', 'a15', ohms), w('w1', pin, 'b15', 'yellow')] : [w('w1', pin, 'b11', 'yellow')]),
    w('w2', P.gnd, 'b10', 'black'),
    { id: 'bat1', type: 'battery' }, { id: 'lamp1', type: 'lamp' },
    ld('ld1', 'bat1.POS', 'lamp1.L1', 'red'), ld('ld2', 'lamp1.L2', 'c12', 'orange'), ld('ld3', 'bat1.NEG', 'c10', 'black')];
  // IRLZ44N low-side switch: the pin drives the gate through 220 ohm, a 10 k pull-down holds it off, source column joined to GND and the battery minus
  const mosParts = (pin, gnd, ldf, o = {}) => {
    const load = o.motor ? 'mot1' : 'lamp1', t1 = o.motor ? 'M1' : 'L1', t2 = o.motor ? 'M2' : 'L2', dc = o.swap ? 'c12' : 'c11', sc = o.swap ? 'c11' : 'c12', gcol = o.swap ? 'b11' : 'b12';
    return [
      { id: 'q1', type: 'mosfet', row: 'e', col: 10 },
      ...(o.nogate ? [] : [res('r1', 'a5', 'a10', 220), w('w1', pin, 'b5', 'yellow'), res('r2', 'd10', 'd14', 10000), w('w3', gnd, 'b14', 'black')]),
      w('w2', gnd, gcol, 'black'),
      { id: 'bat1', type: 'battery' }, { id: load, type: o.motor ? 'motor' : 'lamp' },
      ldf('ld1', 'bat1.POS', load + '.' + t1, 'red'), ldf('ld2', load + '.' + t2, dc, 'orange'), ldf('ld3', 'bat1.NEG', sc, 'black'),
      ...(o.diode ? [{ id: 'd1', type: 'diode', a: 'a11', k: 'a16' }, ldf('ld4', 'mot1.M1', 'a16', 'red')] : [])];
  };
  // RC circuit: pin (through R) charges a capacitor to GND; an LED with 1 k from the capacitor node shows the voltage
  const rcParts = (pin, gnd, o = {}) => [
    w('w1', pin, 'a10', 'yellow'),
    ...(o.noR ? [{ id: 'w5', type: 'wire', from: 'b10', to: 'b14', color: 'orange', lift: 12 }] : [res('r1', 'c10', 'c14', 1000)]),
    { id: 'cap1', type: 'cap', a: o.rev ? 'd15' : 'd14', k: o.rev ? 'd14' : 'd15', uf: 470 },
    w('w2', gnd, 'a15', 'black'),
    res('r2', 'b14', 'b17', 1000), led('led1', 'c17', 'c18'),
    { id: 'w3', type: 'wire', from: 'b15', to: 'b18', color: 'black', lift: 12 }];
  const motorParts = ground => [{ id: 'u1', type: 'l293d', col: 12 }, { id: 'bat1', type: 'battery' }, { id: 'mot1', type: 'motor' },
    w('w1', '5V', 'a12', 'red'), w('w3', 'D5', 'j12', 'orange'), w('w4', 'D7', 'j13', 'yellow'), w('w5', 'D8', 'j18', 'blue'),
    ...(ground ? [w('w6', 'GND3', 'a15', 'black')] : []), ld('ld7', 'bat1.POS', 'j19', 'red'), ld('ld8', 'bat1.NEG', 'j16', 'black'), ld('ld9', 'mot1.M1', 'j14', 'white'), ld('ld10', 'mot1.M2', 'j17', 'green')];
  const list = [
    { title: '✔ LED with a resistor (works)', parts: ledCircuit(false), pins: { [P.sig]: { mode: 'out1' } }, note: `The pin <b>${P.name}</b> is set to <b>Output HIGH</b> (${u3 ? "5 V" : "3.3 V"}), the 220 Ω resistor limits the current to a few mA, and the LED’s long leg (+) faces the pin. Try changing the pin to <b>Input</b>, or the resistor to 100 kΩ.` },
    { title: '✖ LED the wrong way round', parts: ledCircuit(true), pins: { [P.sig]: { mode: 'out1' } }, note: 'Everything is right except the LED: its long leg (anode) faces GND. An LED is a diode, so it only conducts one way. Select the LED and read the reason, then delete it and place it the other way round.' },
    { title: '✖ LED without a resistor', parts: [w('w1', P.v5, 'a10', 'red'), led('led1', 'c10', 'c11'), w('w2', P.gnd, 'd11', 'black')], pins: {}, note: 'The LED is connected straight to 5 V with no resistor. Nothing limits the current, so it burns out in a moment. Press “Replace broken parts”, then put a resistor in the path.' },
    { title: '✔ Button lights an LED (no code)', parts: [{ id: 'sw1', type: 'button', col: 10 }, w('w1', P.v3, 'a10', 'orange'), res('r1', 'g12', 'g16', 220), led('led1', 'i16', 'i17'), w('w2', P.gnd, 'j17', 'black')], pins: {}, note: 'No program needed: 3.3 V → button → resistor → LED → GND. The button is an open switch until you press it, so <b>hold the push button</b> (click and hold it in the 3D view) to complete the circuit.' },
    { title: pi ? '✔ Button on a GPIO input' : '✔ Button on a digital input (pull-up)', parts: [{ id: 'sw1', type: 'button', col: 10 }, w('w1', P.btn, 'a10', 'blue'), w('w2', P.gnd, 'j12', 'black')], pins: { [P.btn]: { mode: 'up' } }, note: `The input pin has its internal pull-up on, so it reads <b>HIGH</b> when nothing is pressed. Pressing the button connects the pin to GND and it reads <b>LOW</b>. Change the pin to “Input (no pull resistor)” and it floats.` },
    { title: u3 ? '✔ Active buzzer beeps by itself' : '⚠ Active buzzer on a 3.3 V pin: too little voltage', parts: [{ id: 'bz1', type: 'buzzer', plus: 'e10', minus: 'e13', active: true }, w('w1', sig8, 'a10', 'yellow'), w('w2', P.gnd, 'a13', 'black')], pins: { [sig8]: { mode: 'out1' } }, note: u3 ? 'An active buzzer has its own oscillator: a steady HIGH on the pin is enough and it beeps at a fixed pitch. (A passive buzzer needs a tone.) It draws about 30 mA, so on an UNO R3 use a transistor for long use.' : 'A 5 V active buzzer draws about 30 mA, and a 3.3 V pin that supplies this sags to about 2.5 V. The common TMB12A05 listings give a supply range of 3 to 7 V, so this is too little: switch the buzzer from a supply with a transistor or a MOSFET. Check the datasheet of your own buzzer.' },
    { title: '✖ Active buzzer connected backwards', parts: [{ id: 'bz1', type: 'buzzer', plus: 'e13', minus: 'e10', active: true }, w('w1', sig8, 'a10', 'yellow'), w('w2', P.gnd, 'a13', 'black')], pins: { [sig8]: { mode: 'out1' } }, note: 'The + leg (marked on the buzzer) must face the pin; here it faces GND, so nothing sounds.' },
    { title: '✔ Buzzer with a tone', parts: [{ id: 'bz1', type: 'buzzer', plus: 'e10', minus: 'e13' }, w('w1', sig8, 'a10', 'yellow'), w('w2', P.gnd, 'a13', 'black')], pins: { [sig8]: { mode: 'tone', freq: 440 } }, note: 'A passive buzzer sounds when the voltage across it changes quickly. The pin is set to <b>Tone</b>, 440 Hz. (Turn the sound on in your browser.)' },
    { title: '✖ Buzzer that stays silent', parts: [{ id: 'bz1', type: 'buzzer', plus: 'e10', minus: 'e13' }, w('w1', sig8, 'a10', 'yellow'), w('w2', P.gnd, 'a13', 'black')], pins: { [sig8]: { mode: 'out1' } }, note: 'Same wiring, but the pin is a steady HIGH. A passive buzzer only clicks when the voltage switches; change the pin to “Tone” and it sounds.' },
    ...(pi ? [] : [
      { title: '✔ Potentiometer on an analog input', parts: [{ id: 'pot1', type: 'pot', row: 'e', col: 10 }, w('w1', P.v3, 'a10', 'orange'), w('w2', P.gnd, 'a14', 'black'), w('w3', P.an, 'a12', 'yellow')], pins: { A0: { mode: 'analog' } }, note: 'The potentiometer is a voltage divider: the wiper (middle leg) outputs a voltage between 0 V and 3.3 V. Turn the knob (drag it in 3D or use the slider) and watch the ADC value change.' },
      { title: '✔ TMP36 temperature sensor', parts: [{ id: 'tmp1', type: 'tmp36', row: 'e', col: 10 }, w('w1', P.v3, 'a10', 'orange'), w('w2', P.an, 'a11', 'yellow'), w('w3', P.gnd, 'a12', 'black')], pins: { A0: { mode: 'analog' } }, note: 'The TMP36 puts out 0.5 V + 10 mV per °C. Tick “turn round” in the left column and place it the other way: +VS and GND swap, and the sensor is connected backwards.' },
    ]),
    ...(pi ? [
      { title: '✖ HC-SR04 echo straight into a GPIO pin', parts: [{ id: 'us1', type: 'hcsr04', row: 'j', col: 11 }, w('w1', 'p2', 'i11', 'red'), w('w2', 'p11', 'i12', 'yellow'), w('w3', 'p13', 'i13', 'blue'), w('w4', 'p9', 'i14', 'black')], pins: { p11: { mode: 'pulse' }, p13: { mode: 'in' } }, note: 'The HC-SR04 runs on 5 V, so its ECHO output is 5 V, and a Raspberry Pi GPIO pin is 3.3 V only. This connection damages the pin. Press “Replace broken parts”, then use the voltage divider example.' },
      { title: '✔ HC-SR04 with a voltage divider', parts: [{ id: 'us1', type: 'hcsr04', row: 'j', col: 11 }, w('w1', 'p2', 'i11', 'red'), w('w2', 'p11', 'i12', 'yellow'), res('r1', 'h13', 'h17', 1000), res('r2', 'g17', 'g21', 2200), w('w3', 'p13', 'i17', 'blue'), w('w4', 'p9', 'i14', 'black'), w('w5', 'p14', 'i21', 'black')], pins: { p11: { mode: 'pulse' }, p13: { mode: 'in' } }, note: 'Two resistors (1 kΩ and 2.2 kΩ) divide the 5 V echo signal down to about 3.3 V, which a Raspberry Pi GPIO pin accepts. Drag the obstacle slider and watch the echo pulse change.' },
    ] : [
      { title: '✔ HC-SR04 distance sensor', parts: [{ id: 'us1', type: 'hcsr04', row: 'j', col: 11 }, w('w1', '5V', 'i11', 'red'), w('w2', 'D7', 'i12', 'yellow'), w('w3', 'D8', 'i13', 'blue'), w('w4', 'GND2', 'i14', 'black')], pins: { D7: { mode: 'pulse' }, D8: { mode: 'in' } }, note: u3 ? 'VCC on 5 V, TRIG on D7 (sends the 10 µs pulse), ECHO on D8. The UNO R3 works at 5 V, so the 5 V echo is fine on any pin.' : 'VCC on 5 V, TRIG on D7 (sends the 10 µs pulse), ECHO on D8, which tolerates 5 V as an input. The echo pulse lasts 58 µs per centimetre. Move the obstacle slider.' },
      ...(u3 ? [] : [{ title: '✖ HC-SR04 echo on D3', parts: [{ id: 'us1', type: 'hcsr04', row: 'j', col: 11 }, w('w1', '5V', 'i11', 'red'), w('w2', 'D7', 'i12', 'yellow'), w('w3', 'D3', 'i13', 'blue'), w('w4', 'GND2', 'i14', 'black')], pins: { D7: { mode: 'pulse' }, D3: { mode: 'in' } }, note: 'D3 tolerates only 3.6 V, and the HC-SR04 echo is 5 V. Use D8 instead (a 5 V-tolerant pin).' }]),
    ]),
    { title: '✔ PIR motion sensor', parts: [{ id: 'pir1', type: 'pir' }, w('w1', 'pir1.VCC', 'a10', 'red'), w('w2', 'pir1.OUT', 'a11', 'yellow'), w('w3', 'pir1.GND', 'a12', 'black'), w('w4', P.v5, 'b10', 'red'), w('w5', P.btn, 'b11', 'blue'), w('w6', P.gnd, 'b12', 'black')], pins: { [P.btn]: { mode: 'in' } }, note: 'The PIR sensor is powered from 5 V and its OUT wire goes to an input pin (3.3 V when it sees motion, so it is safe for any pin). Hold the “wave a hand” button in the right column.' },
    { title: '✔ Servo motor', parts: [{ id: 'sv1', type: 'servo', row: 'j', col: 11 }, w('w1', P.gnd, 'i11', 'black'), w('w2', P.v5, 'i12', 'red'), w('w3', P.sig, 'i13', 'orange')], pins: { [P.sig]: { mode: 'servo', angle: 45 } }, note: 'Servo plug: brown = GND, red = 5 V (middle), orange = signal. The pin sends 50 Hz pulses; the pulse width sets the angle. Move the angle slider.' },
    { title: '✖ Servo on 3.3 V', parts: [{ id: 'sv1', type: 'servo', row: 'j', col: 11 }, w('w1', P.gnd, 'i11', 'black'), w('w2', P.v3, 'i12', 'orange'), w('w3', P.sig, 'i13', 'orange')], pins: { [P.sig]: { mode: 'servo', angle: 45 } }, note: 'An SG90 servo needs 4.8–6 V. On 3.3 V it does not move (or only twitches). Use the 5 V pin.' },
    { title: '✔ SHT31-D temperature and humidity (I²C)', parts: [{ id: 'sen1', type: 'sht31', row: 'g', col: 10 }, w('w1', P.v3, 'j10', 'red'), w('w2', P.gnd, 'j11', 'black'), w('w3', pi ? 'p5' : u3 ? 'A5' : 'D21', 'j12', 'yellow'), w('w4', pi ? 'p3' : u3 ? 'A4' : 'D20', 'j13', 'blue')], pins: pi ? { p5: { mode: 'i2c' }, p3: { mode: 'i2c' } } : u3 ? { A5: { mode: 'i2c' }, A4: { mode: 'i2c' } } : { D21: { mode: 'i2c' }, D20: { mode: 'i2c' } }, note: 'Four wires: VIN to 3.3 V, GND, SCL (clock) and SDA (data) to the board’s I²C pins. The breakout has its own pull-up resistors on SCL and SDA. Change the temperature and humidity of the room on the right.' },
    { title: '✖ SHT31-D with SDA and SCL swapped', parts: [{ id: 'sen1', type: 'sht31', row: 'g', col: 10 }, w('w1', P.v3, 'j10', 'red'), w('w2', P.gnd, 'j11', 'black'), w('w3', pi ? 'p3' : u3 ? 'A4' : 'D20', 'j12', 'yellow'), w('w4', pi ? 'p5' : u3 ? 'A5' : 'D21', 'j13', 'blue')], pins: pi ? { p5: { mode: 'i2c' }, p3: { mode: 'i2c' } } : u3 ? { A5: { mode: 'i2c' }, A4: { mode: 'i2c' } } : { D21: { mode: 'i2c' }, D20: { mode: 'i2c' } }, note: 'A classic mistake: the clock wire is on the data pin and the data wire on the clock pin. Nothing is damaged, but the sensor never answers. Swap the two wires.' },
    { title: '✔ Relay switches a lamp (own battery)', parts: [{ id: 'rel1', type: 'relay' }, { id: 'bat1', type: 'battery' }, { id: 'lamp1', type: 'lamp' }, ...relayWires], pins: { [relayPin]: { mode: 'out0' } }, note: 'The relay module is low-level triggered: the pin goes LOW and the coil clicks on, joining COM to NO. The lamp has its own 6 V battery (+ → COM, NO → lamp, lamp → −), so the board only drives the relay. Change the pin to “Input” to release the relay.' },
    { title: '✖ Relay never switches (pin HIGH)', parts: [{ id: 'rel1', type: 'relay' }, { id: 'bat1', type: 'battery' }, { id: 'lamp1', type: 'lamp' }, ...relayWires], pins: { [relayPin]: { mode: 'out1' } }, note: u3 ? 'This module switches on when its input is pulled LOW. With the pin HIGH (5 V) the relay stays off, so the lamp stays dark. Set the pin to Output LOW to switch it on.' : 'This module switches on when its input is pulled LOW. With the pin HIGH the lamp stays dark, and 3.3 V HIGH from a pin does not even switch a 5 V module off cleanly: release it by setting the pin to Input.' },
    { title: '✖ Battery short circuit', parts: [{ id: 'bat1', type: 'battery' }, { id: 'ld1', type: 'lead', from: 'bat1.POS', to: 'bat1.NEG', color: 'red', lift: 14 }], pins: {}, note: 'A wire from battery + to battery − with nothing in between: a huge current flows and the batteries would get dangerously hot. Never do this with real batteries.' },
    ...(pi ? [] : [
      { title: '✔ DC motor with an L293D driver', parts: motorParts(true), pins: { D5: { mode: 'out1' }, D7: { mode: 'out1' }, D8: { mode: 'out0' } }, note: 'The driver chip is an H-bridge: EN (D5) enables it, and the inputs D7 / D8 choose the direction (HIGH/LOW = direction 1, LOW/HIGH = the other way, equal = brake). The motor has its own battery on pin 8 (VCC2); the logic runs from 5 V on pin 16. Change D7 and D8.' },
      { title: '✖ Motor driver without a common ground', parts: motorParts(false), pins: { D5: { mode: 'out1' }, D7: { mode: 'out1' }, D8: { mode: 'out0' } }, note: 'Everything looks right, but the battery − and the driver’s GND pins are not joined to a GND pin of the board. Signals need a shared ground reference, so the driver ignores the inputs. Add the missing GND wire.' },
    ]),
    ...(pi || u3 ? [] : [
      { title: '✔ Modulino Thermo over Qwiic', parts: [{ id: 'th1', type: 'thermo' }, { id: 'cab1', type: 'qwiic', from: 'QWIIC', to: 'th1.QA', lift: 4 }], pins: {}, note: 'One Qwiic cable gives the module power (3.3 V) and the I²C bus (data and clock). The cable can only be plugged in one way, so it cannot be connected wrongly. Change the room temperature and humidity on the right.' },
      { title: '✔ Thermo + Pixels chain', parts: [{ id: 'th1', type: 'thermo' }, { id: 'pix1', type: 'pixels' }, { id: 'cab1', type: 'qwiic', from: 'QWIIC', to: 'th1.QA', lift: 4 }, { id: 'cab2', type: 'qwiic', from: 'th1.QB', to: 'pix1.QA', lift: 3 }], pins: {}, note: 'Modules are chained: each has two Qwiic sockets, so the second cable goes from the Thermo’s free socket to the Pixels. In an example sketch the Pixels draw a thermometer bar from the Thermo reading. Change the temperature.' },
      { title: '✖ Qwiic cable not connected to the board', parts: [{ id: 'th1', type: 'thermo' }, { id: 'pix1', type: 'pixels' }, { id: 'cab2', type: 'qwiic', from: 'th1.QB', to: 'pix1.QA', lift: 3 }], pins: {}, note: 'The two modules are joined, but nothing connects them to the board’s Qwiic port, so they get no power and no data. Add the cable from the board to a module.' },
    ]),
    ...(u3 ? [{ title: '✖ Output pin wired straight to GND', parts: [w('w1', 'D5', 'a10', 'yellow'), w('w2', 'GND2', 'b10', 'black')], pins: { D5: { mode: 'out1' } }, note: 'D5 is set to Output HIGH (5 V) and a wire joins it directly to GND, with nothing to limit the current. The pin would have to deliver far more than its 40 mA absolute maximum and is damaged. Always put a load (with a resistor) between a pin and GND.' }] : [{ title: '✖ 5 V on a 3.3 V pin', parts: [w('w1', P.v5, 'a10', 'red'), w('w2', P.bad5, 'b10', 'yellow')], pins: { [P.bad5]: { mode: 'in' } }, note: pi ? 'Raspberry Pi GPIO pins are 3.3 V only. 5 V on a GPIO pin can damage the Raspberry Pi permanently.' : 'D3 tolerates only 3.6 V. 5 V on it can damage the UNO Q permanently.' }]),
    { title: '✔ RGB LED (common cathode) with three resistors', parts: [{ id: 'rgb1', type: 'rgbled', row: 'e', col: 10 }, res('r1', 'a10', 'a16', 220), res('r2', 'a12', 'a17', 220), res('r3', 'a13', 'a18', 220), w('w1', P.rgb[0], 'b16', 'red'), w('w2', P.rgb[1], 'b17', 'green'), w('w3', P.rgb[2], 'b18', 'blue'), w('w4', P.rgbGnd, 'a11', 'black')], pins: { [P.rgb[0]]: { mode: 'pwm', duty: 0.8 }, [P.rgb[1]]: { mode: 'pwm', duty: 0.5 }, [P.rgb[2]]: { mode: 'pwm', duty: 0.1 } }, note: 'Red, green and blue legs each go through their own resistor to a PWM pin, the longest (common) leg goes to GND. The three duty cycles mix the colour: change them in the pin panel. ' + (u3 ? '' : 'On a 3.3 V board the green and blue dice (about 3 V) get much less current than red, so they look dimmer.') },
    { title: '✖ RGB LED without resistors', parts: [{ id: 'rgb1', type: 'rgbled', row: 'e', col: 10 }, w('w1', P.rgb[0], 'b10', 'red'), w('w2', P.rgb[1], 'b12', 'green'), w('w3', P.rgb[2], 'b13', 'blue'), w('w4', P.rgbGnd, 'b11', 'black')], pins: { [P.rgb[0]]: { mode: 'out1' }, [P.rgb[1]]: { mode: 'out1' }, [P.rgb[2]]: { mode: 'out1' } }, note: u3 ? 'The colour legs are wired straight to 5 V pins. Nothing limits the current through the three dice, so the LED burns out. Add a resistor in each colour line.' : 'The colour legs are wired straight to 3.3 V pins. Here only the small resistance inside the pin limits the current, and the red die already gets about 26 mA (its rating is about 20 mA). Never do this: add a resistor in each colour line.' },
    { title: '✖ Common-anode LED wired like a common-cathode one', parts: [{ id: 'rgb1', type: 'rgbled', row: 'e', col: 10, ca: true }, res('r1', 'a10', 'a16', 220), res('r2', 'a12', 'a17', 220), res('r3', 'a13', 'a18', 220), w('w1', P.rgb[0], 'b16', 'red'), w('w2', P.rgb[1], 'b17', 'green'), w('w3', P.rgb[2], 'b18', 'blue'), w('w4', P.rgbGnd, 'a11', 'black')], pins: { [P.rgb[0]]: { mode: 'out1' }, [P.rgb[1]]: { mode: 'out1' }, [P.rgb[2]]: { mode: 'out1' } }, note: 'A common-anode LED has its common leg on the supply, not on GND, and a colour lights when its pin is LOW. Here the common leg is on GND and the pins are HIGH, so nothing lights. Move the common leg to 3.3 V (or 5 V) and set the pins to Output LOW.' },
    { title: '✔ DHT11 temperature and humidity', parts: [{ id: 'dht1', type: 'dht', model: 'dht11', row: 'e', col: 10 }, w('w1', P.dhtV, 'a10', 'red'), w('w2', P.dhtPin, 'a11', 'yellow'), res('r1', 'c10', 'c16', pi ? 4700 : 10000), w('w3', 'b11', 'b16', 'orange'), w('w4', P.gnd, 'a13', 'black')], pins: { [P.dhtPin]: { mode: 'dht' } }, note: 'Pins from the left: VCC, DATA, (not connected), GND. VCC goes to ' + (u3 ? '5 V' : '3.3 V') + ', DATA to a pin set to “Single-wire data”, and a ' + (pi ? '4.7 kΩ' : '10 kΩ') + ' pull-up resistor joins DATA and VCC. Change the room temperature and humidity on the right.' + (!u3 && !pi ? ' (On the UNO Q the Adafruit DHT library is reported to return NaN: use the Modulino Thermo or SHT31 there.)' : '') },
    { title: '✖ DHT without the pull-up resistor', parts: [{ id: 'dht1', type: 'dht', model: 'dht11', row: 'e', col: 10 }, w('w1', P.dhtV, 'a10', 'red'), w('w2', P.dhtPin, 'a11', 'yellow'), w('w4', P.gnd, 'a13', 'black')], pins: { [P.dhtPin]: { mode: 'dht' } }, note: 'The sensor pulls the DATA line low to send bits but cannot pull it up: it needs a resistor between DATA and VCC. Without it the board never receives a reading (the Adafruit library returns NaN). Add a 10 kΩ resistor between DATA and VCC.' },
    ...(pi ? [] : [
      { title: '✔ Joystick module (two analog axes + switch)', parts: [{ id: 'joy1', type: 'joystick', row: 'g', col: 10 }, w('w1', P.gnd, 'j10', 'black'), w('w2', P.joyV, 'j11', 'red'), w('w3', 'A0', 'j12', 'green'), w('w4', 'A1', 'j13', 'blue'), w('w5', 'D2', 'j14', 'yellow')], pins: { A0: { mode: 'analog' }, A1: { mode: 'analog' }, D2: { mode: 'up' } }, note: 'VRx goes to A0 and VRy to A1 (analog inputs), SW to D2 with the internal pull-up. Move the stick with the X and Y sliders on the right: at the centre each axis is about half the supply voltage. Hold the switch button to press the stick.' + (u3 ? '' : ' The analog pins of this board are 3.3 V only, so the module is powered from 3.3 V.') },
      ...(u3 ? [] : [{ title: '✖ Joystick powered from 5 V', parts: [{ id: 'joy1', type: 'joystick', row: 'g', col: 10 }, w('w1', P.gnd, 'j10', 'black'), w('w2', '5V', 'j11', 'red'), w('w3', 'A0', 'j12', 'green'), w('w4', 'A1', 'j13', 'blue')], pins: { A0: { mode: 'analog' }, A1: { mode: 'analog' } }, note: 'On 5 V the stick outputs go up to 5 V, but the analog pins of this board are 3.3 V only: a stick pushed to the right (X slider) or down (Y slider) can damage A0 and A1. Power the module from 3.3 V.' }]),
    ]),
    { title: '✔ Rotary encoder (CLK, DT, SW with pull-ups)', parts: [{ id: 'enc1', type: 'encoder', row: 'g', col: 10 }, w('w1', pi ? 'p11' : 'D2', 'j10', 'green'), w('w2', pi ? 'p13' : 'D4', 'j11', 'blue'), w('w3', pi ? 'p15' : 'D7', 'j12', 'yellow'), w('w4', P.encV, 'j13', 'red'), w('w5', P.gnd, 'j14', 'black')], pins: pi ? { p11: { mode: 'up' }, p13: { mode: 'up' }, p15: { mode: 'up' } } : { D2: { mode: 'up' }, D4: { mode: 'up' }, D7: { mode: 'up' } }, note: 'The knob closes CLK and DT to GND in a shifted pattern. Use “step ▶” and “◀ step” on the right and watch the two pins change one after the other: which one changes first is the direction. The pins use the internal pull-up.' },
    { title: '✖ Rotary encoder pins without pull-ups', parts: [{ id: 'enc1', type: 'encoder', row: 'g', col: 10 }, w('w1', pi ? 'p11' : 'D2', 'j10', 'green'), w('w2', pi ? 'p13' : 'D4', 'j11', 'blue'), w('w3', pi ? 'p15' : 'D7', 'j12', 'yellow'), w('w4', P.encV, 'j13', 'red'), w('w5', P.gnd, 'j14', 'black')], pins: pi ? { p11: { mode: 'in' }, p13: { mode: 'in' }, p15: { mode: 'in' } } : { D2: { mode: 'in' }, D4: { mode: 'in' }, D7: { mode: 'in' } }, note: 'The contacts only connect the pins to GND, so when they are open the pins float and read random values. Set CLK, DT and SW to “Input with pull-up”.' },
    { title: '✔ NeoPixel strip (8 pixels) on one data pin', parts: neoParts(P.neoVcc, P.neoDin, P.neoGnd), pins: { [P.neoDin]: { mode: 'neopixel', pattern: 'rainbow', bright: 40 } }, note: 'Three connections: 5 V, data in (DIN) and GND. The data pin is set to “Pixel data”: pick a pattern and the brightness in the pin panel. At brightness 40 the strip draws well under 100 mA; at full white 8 pixels could draw up to 480 mA.' + (u3 ? '' : pi ? ' The Adafruit Raspberry Pi example uses GPIO18 for the data line, and the program must run as root.' : ' The 5 V strip is driven by a 3.3 V data pin here: see the next example.') },
    ...(u3 ? [] : [{ title: '✖ 5 V NeoPixels with a 3.3 V data pin', parts: neoParts(P.neoVcc, P.neoDin, P.neoGnd), pins: { [P.neoDin]: { mode: 'neopixel', pattern: 'rainbow', bright: 40 } }, note: 'The strip runs at 5 V, so its data input needs at least 70 % of that, 3.5 V (Adafruit). A 3.3 V pin is just below it, so the pixels may show wrong colours or nothing. Fix: a level shifter between the pin and DIN, or a lower strip supply voltage.' }]),
    { title: '✖ NeoPixels at full white', parts: neoParts(P.neoVcc, P.neoDin, P.neoGnd), pins: { [P.neoDin]: { mode: 'neopixel', pattern: 'white', bright: 255 } }, note: 'All 8 pixels at full white draw up to 60 mA each: about 480 mA, close to the 500 mA a USB port can give for the whole board. Lower the brightness.' },
    { title: '✔ LCD 16×2 with I²C backpack', parts: i2cDisp('lcd1602', 'lcd1', P.i2cV5, P.sda, P.scl), pins: { [P.sda]: { mode: 'i2c' }, [P.scl]: { mode: 'i2c' } }, note: 'Four wires: GND, VCC (5 V: the LCD is made for 5 V), SDA and SCL to the I²C pins. The backpack answers at address 0x27 (0x3F on some); the text comes from the two lines on the right.' + (u3 ? '' : ' Many backpacks pull SDA and SCL up to VCC: on this 3.3 V board that puts 5 V on the pins, so check your module or use a level shifter.') },
    { title: '✖ LCD powered from 3.3 V', parts: i2cDisp('lcd1602', 'lcd1', P.i2cV3, P.sda, P.scl), pins: { [P.sda]: { mode: 'i2c' }, [P.scl]: { mode: 'i2c' } }, note: 'The LCD and its backpack are made for 5 V. On 3.3 V the backlight may light, but the characters are not readable. Use the 5 V pin.' },
    { title: '✔ OLED 128×64 (SSD1306, I²C)', parts: i2cDisp('oled', 'oled1', P.i2cV3, P.sda, P.scl), pins: { [P.sda]: { mode: 'i2c' }, [P.scl]: { mode: 'i2c' } }, note: 'Four wires: GND, VCC, SCL, SDA (the order differs between makers: read the printing). The display answers at address 0x3C (0x3D on some modules). Check whether your module accepts 3.3 V, 5 V or both.' },
    { title: '✖ OLED with SDA and SCL swapped', parts: i2cDisp('oled', 'oled1', P.i2cV3, P.scl, P.sda), pins: { [P.sda]: { mode: 'i2c' }, [P.scl]: { mode: 'i2c' } }, note: 'The clock wire is on the data pin and the data wire on the clock pin: the screen stays dark. Swap the two wires.' },
    { title: '✔ Transistor switches a 6 V lamp', parts: qLamp(P.sig, u3 ? 1000 : 470, false, false), pins: { [P.sig]: { mode: 'out1' } }, note: 'The pin cannot drive a lamp that needs about 300 mA. It drives the BASE of a PN2222A through a resistor (a few mA); the transistor then lets the lamp’s current flow from the 6 V pack through the collector to the emitter and GND. The battery − and the board GND are joined at the emitter column. Set the pin to Output LOW and the lamp goes out.' },
    { title: '✖ Transistor without a base resistor', parts: qLamp(P.sig, 0, false, false), pins: { [P.sig]: { mode: 'out1' } }, note: 'The base is wired straight to the pin. The base-emitter junction is a diode, so nothing limits the current: the pin has to deliver far more than it can and is damaged. Always put a resistor (about 1 kΩ) in the base line.' },
    { title: '✖ Base resistor too large (100 kΩ)', parts: qLamp(P.sig, 100000, false, false), pins: { [P.sig]: { mode: 'out1' } }, note: 'Only about 40 µA flows into the base, so the collector current is far too small and the lamp stays dark. For a switch the base current should be about one tenth of the load current.' },
    { title: '✖ Emitter and collector swapped', parts: qLamp(P.sig, u3 ? 1000 : 470, true, false), pins: { [P.sig]: { mode: 'out1' } }, note: 'The transistor is turned round: the PN2222A (flat side toward you) has emitter, base, collector from left to right. Swapped, nothing switches and the lamp stays dark. Other transistor types have a different pin order: always check the datasheet.' },
    { title: '✔ Diode: current flows one way', parts: [w('w1', P.v3, 'a10', 'orange'), { id: 'd1', type: 'diode', a: 'b10', k: 'b14' }, res('r1', 'c14', 'c18', 1000), led('led1', 'd18', 'd19'), w('w2', P.gnd, 'e19', 'black')], pins: {}, note: 'Current flows from the anode through the diode to the cathode (the end with the silver band): the LED lights, and the diode costs about 0.7 – 0.9 V of the supply. Delete the diode and place it the other way round: it blocks the current and the LED goes out.' },
    { title: '✔ MOSFET switches a 6 V lamp', parts: mosParts(P.sig, P.gnd, ld), pins: { [P.sig]: { mode: 'out1' } }, note: 'The pin drives the GATE of an IRLZ44N through 220 Ω. The gate takes no steady current: only its voltage matters. The MOSFET lets the lamp current flow from the 6 V pack through the drain to the source and GND. The 10 kΩ resistor from gate to GND keeps it OFF while the pin is not yet an output. Set the pin to Output LOW and the lamp goes out.' },
    { title: u3 ? '✔ MOSFET switches a motor (about 1 A) with a flyback diode' : '⚠ MOSFET switches a motor from a 3.3 V pin', parts: mosParts(P.sig, P.gnd, ld, { motor: true, diode: true }), pins: { [P.sig]: { mode: 'out1' } }, note: u3 ? 'The motor takes about 1 A, more than the 600 mA a PN2222A can carry: the MOSFET handles it easily (its on-resistance at 5 V is 25 mΩ). The 1N4007 across the motor (cathode band to the battery side) absorbs the voltage spike when the motor is switched off.' : 'The motor takes about 1 A. The IRLZ44N datasheet guarantees its on-resistance only for a gate voltage of 4 V and above (35 mΩ at 4 V) and gives no value at 3.3 V, so the app warns. Many real parts do switch at 3.3 V, but it is not guaranteed: for a motor use a 5 V gate drive or a gate driver.' },
    { title: '✖ MOSFET motor without a flyback diode', parts: mosParts(P.sig, P.gnd, ld, { motor: true }), pins: { [P.sig]: { mode: 'out1' } }, note: 'When the motor is switched off, its coil keeps pushing current and makes a voltage spike far above the supply. Without a diode across the motor, the spike can destroy the MOSFET.' },
    { title: '✖ MOSFET gate not connected', parts: mosParts(P.sig, P.gnd, ld, { nogate: true }), pins: {}, note: 'The gate is left floating. A MOSFET gate holds charge and can switch the load on or off by itself, even from a hand nearby. Always drive the gate from a pin and add a resistor from gate to GND.' },
    { title: '✖ MOSFET drain and source swapped', parts: mosParts(P.sig, P.gnd, ld, { swap: true }), pins: { [P.sig]: { mode: 'out1' } }, note: 'The load is on the source leg and GND on the drain leg. The built-in body diode (source to drain) now conducts, so the lamp is on whatever the gate does and cannot be switched off. The TO-220 pins are gate, drain, source from left to right (text toward you).' },
    { title: '✔ Capacitor charges slowly: the LED fades in', parts: rcParts(P.sig, P.gnd), pins: { [P.sig]: { mode: 'out1' } }, note: 'The pin charges a 470 µF capacitor through 1 kΩ: τ = R × C = 0.47 s, so the voltage across the capacitor (and the LED brightness) rises gradually. After about 5 τ it is full.' },
    { title: '✔ Capacitor keeps the LED glowing after the pin goes LOW', parts: rcParts(P.sig, P.gnd), caps: { cap1: 3.4 }, pins: { [P.sig]: { mode: 'out0' } }, note: 'The capacitor starts charged (3.4 V). With the pin LOW it discharges through the LED branch and through the 1 kΩ resistor to the pin, so the LED fades out over a fraction of a second instead of switching off at once.' },
    { title: '✖ Capacitor connected backwards', parts: rcParts(P.sig, P.gnd, { rev: true }), pins: { [P.sig]: { mode: 'out1' } }, note: 'The + leg is toward GND and the stripe (−) toward the resistor. An electrolytic capacitor is polarised: with voltage the wrong way round it fails (in real life it can vent or burst).' },
    { title: '✖ Capacitor straight from a pin (no resistor)', parts: rcParts(P.sig, P.gnd, { noR: true }), pins: { [P.sig]: { mode: 'out1' } }, note: 'An empty capacitor acts like a short circuit for a moment: with nothing to limit the inrush current, the pin has to deliver far more than it can and is damaged. Always charge through a resistor.' },
    { title: '✖ Short circuit', parts: [w('w1', P.v5, 'r:top+:3', 'red'), w('w2', P.gnd, 'r:top+:4', 'black')], pins: {}, note: 'The 5 V pin and a GND pin are joined by the same power rail. Nothing limits the current, so the power would be cut (here the cable pops out).' },
  ];
  return list;
}

// ESP32 DevKit V1: 3.3 V logic, pins are written by GPIO number (G16 = GPIO16). Pin wires are female–male (fwire).
function EXAMPLES_E32() {
  const w = (id, from, to, color) => ({ id, type: isHoleRef(from) ? 'wire' : 'fwire', from, to, color, lift: isHoleRef(from) && isHoleRef(to) ? 12 : 26 });
  const led = (id, anode, cathode, color = 'red') => ({ id, type: 'led', anode, cathode, color });
  const res = (id, a, b, ohms) => ({ id, type: 'resistor', a, b, ohms });
  const ledCircuit = (flip, ohms = 220) => [w('w1', 'G16', 'a10', 'yellow'), res('r1', 'b10', 'b14', ohms), flip ? led('led1', 'c15', 'c14') : led('led1', 'c14', 'c15'), w('w2', 'GND2', 'd15', 'black')];
  const ldE = (id, from, to, color) => ({ id, type: 'lead', from, to, color, lift: 14 });
  const i2cDispE = (type, id, vcc, sdaPin, sclPin) => {
    const order = type === 'lcd1602' ? ['GND', 'VCC', 'SDA', 'SCL'] : ['GND', 'VCC', 'SCL', 'SDA'], pinFor = { GND: 'GND2', VCC: vcc, SDA: sdaPin, SCL: sclPin }, colour = { GND: 'black', VCC: 'red', SDA: 'blue', SCL: 'yellow' };
    return [{ id, type }, ...order.map((n, i) => ({ id: 'm' + (i + 1), type: 'fwire', from: id + '.' + n, to: 'a' + (10 + i), color: colour[n], lift: 16 })), ...order.map((n, i) => w('w' + (i + 1), pinFor[n], 'b' + (10 + i), colour[n]))];
  };
  const qLampE = (pin, ohms, flip) => [
    { id: 'q1', type: 'npn', row: 'e', col: 10, flip: !!flip },
    ...(ohms ? [res('r1', 'a11', 'a15', ohms), w('w1', pin, 'b15', 'yellow')] : [w('w1', pin, 'b11', 'yellow')]),
    w('w2', 'GND2', 'b10', 'black'),
    { id: 'bat1', type: 'battery' }, { id: 'lamp1', type: 'lamp' },
    ldE('ld1', 'bat1.POS', 'lamp1.L1', 'red'), ldE('ld2', 'lamp1.L2', 'c12', 'orange'), ldE('ld3', 'bat1.NEG', 'c10', 'black')];
  // IRLZ44N low-side switch: the pin drives the gate through 220 ohm, a 10 k pull-down holds it off, source column joined to GND and the battery minus
  const mosParts = (pin, gnd, ldf, o = {}) => {
    const load = o.motor ? 'mot1' : 'lamp1', t1 = o.motor ? 'M1' : 'L1', t2 = o.motor ? 'M2' : 'L2', dc = o.swap ? 'c12' : 'c11', sc = o.swap ? 'c11' : 'c12', gcol = o.swap ? 'b11' : 'b12';
    return [
      { id: 'q1', type: 'mosfet', row: 'e', col: 10 },
      ...(o.nogate ? [] : [res('r1', 'a5', 'a10', 220), w('w1', pin, 'b5', 'yellow'), res('r2', 'd10', 'd14', 10000), w('w3', gnd, 'b14', 'black')]),
      w('w2', gnd, gcol, 'black'),
      { id: 'bat1', type: 'battery' }, { id: load, type: o.motor ? 'motor' : 'lamp' },
      ldf('ld1', 'bat1.POS', load + '.' + t1, 'red'), ldf('ld2', load + '.' + t2, dc, 'orange'), ldf('ld3', 'bat1.NEG', sc, 'black'),
      ...(o.diode ? [{ id: 'd1', type: 'diode', a: 'a11', k: 'a16' }, ldf('ld4', 'mot1.M1', 'a16', 'red')] : [])];
  };
  // RC circuit: pin (through R) charges a capacitor to GND; an LED with 1 k from the capacitor node shows the voltage
  const rcParts = (pin, gnd, o = {}) => [
    w('w1', pin, 'a10', 'yellow'),
    ...(o.noR ? [{ id: 'w5', type: 'wire', from: 'b10', to: 'b14', color: 'orange', lift: 12 }] : [res('r1', 'c10', 'c14', 1000)]),
    { id: 'cap1', type: 'cap', a: o.rev ? 'd15' : 'd14', k: o.rev ? 'd14' : 'd15', uf: 470 },
    w('w2', gnd, 'a15', 'black'),
    res('r2', 'b14', 'b17', 1000), led('led1', 'c17', 'c18'),
    { id: 'w3', type: 'wire', from: 'b15', to: 'b18', color: 'black', lift: 12 }];
  const neoE32 = (vcc, din, gnd) => [{ id: 'neo1', type: 'neopixel' }, ldE('ld1', 'neo1.VCC', 'a10', 'red'), ldE('ld2', 'neo1.DIN', 'a11', 'yellow'), ldE('ld3', 'neo1.GND', 'a12', 'black'), w('w1', vcc, 'b10', 'red'), w('w2', din, 'b11', 'yellow'), w('w3', gnd, 'b12', 'black')];
  return [
    { title: '✔ LED with a resistor (works)', parts: ledCircuit(false), pins: { G16: { mode: 'out1' } }, note: 'GPIO16 is set to <b>Output HIGH</b> (3.3 V), the 220 Ω resistor limits the current to about 5 mA, and the LED’s long leg (+) faces the pin. Try changing the pin to <b>Input</b>, or the resistor to 100 kΩ.' },
    { title: '✖ LED the wrong way round', parts: ledCircuit(true), pins: { G16: { mode: 'out1' } }, note: 'Everything is right except the LED: its long leg (anode) faces GND. An LED only conducts one way. Select the LED, read the reason, then place it the other way round.' },
    { title: '✔ Button on a digital input (pull-up)', parts: [{ id: 'sw1', type: 'button', col: 10 }, w('w1', 'G17', 'a10', 'blue'), w('w2', 'GND2', 'j12', 'black')], pins: { G17: { mode: 'up' } }, note: 'GPIO17 has its internal pull-up (about 45 kΩ) on, so it reads <b>HIGH</b> when nothing is pressed. Pressing the button connects the pin to GND and it reads <b>LOW</b>. Change the mode to “Input (no pull resistor)” and the pin floats.' },
    { title: '✖ Button on GPIO34 with pull-up', parts: [{ id: 'sw1', type: 'button', col: 10 }, w('w1', 'G34', 'a10', 'blue'), w('w2', 'GND2', 'j12', 'black')], pins: { G34: { mode: 'in' } }, note: 'GPIO34 is input only and has <b>no internal pull-up</b>, so it floats until the button is pressed. Move the wire to GPIO17 (which has a pull-up) or add an external resistor from the pin to 3V3.' },
    { title: '⚠ Active buzzer on a 3.3 V pin: too little voltage', parts: [{ id: 'bz1', type: 'buzzer', plus: 'e10', minus: 'e13', active: true }, w('w1', 'G16', 'a10', 'yellow'), w('w2', 'GND2', 'a13', 'black')], pins: { G16: { mode: 'out1' } }, note: 'A 5 V active buzzer draws about 30 mA, and a 3.3 V pin that supplies this sags to about 2.5 V. The common TMB12A05 listings give a supply range of 3 to 7 V, so this is too little: switch the buzzer from a supply with a transistor or a MOSFET. Check the datasheet of your own buzzer.' },
    { title: '✖ Active buzzer connected backwards', parts: [{ id: 'bz1', type: 'buzzer', plus: 'e13', minus: 'e10', active: true }, w('w1', 'G16', 'a10', 'yellow'), w('w2', 'GND2', 'a13', 'black')], pins: { G16: { mode: 'out1' } }, note: 'The + leg (marked on the buzzer) must face the pin; here it faces GND, so nothing sounds.' },
    { title: '✔ Buzzer with a tone', parts: [{ id: 'bz1', type: 'buzzer', plus: 'e10', minus: 'e13' }, w('w1', 'G16', 'a10', 'yellow'), w('w2', 'GND2', 'a13', 'black')], pins: { G16: { mode: 'tone', freq: 440 } }, note: 'A passive buzzer sounds when the voltage across it changes quickly. The pin is set to <b>Tone</b>, 440 Hz. (Turn the sound on in your browser.)' },
    { title: '✔ Potentiometer on an analog input', parts: [{ id: 'pot1', type: 'pot', row: 'e', col: 10 }, w('w1', '3V3', 'a10', 'orange'), w('w2', 'GND2', 'a14', 'black'), w('w3', 'G34', 'a12', 'yellow')], pins: { G34: { mode: 'analog' } }, note: 'The potentiometer is a voltage divider: the wiper (middle leg) outputs 0 V to 3.3 V. The ESP32’s ADC gives 0 … 4095. Turn the knob (drag it in 3D or use the slider).' },
    { title: '✔ TMP36 temperature sensor', parts: [{ id: 'tmp1', type: 'tmp36', row: 'e', col: 10 }, w('w1', '3V3', 'a10', 'orange'), w('w2', 'G34', 'a11', 'yellow'), w('w3', 'GND2', 'a12', 'black')], pins: { G34: { mode: 'analog' } }, note: 'The TMP36 puts out 0.5 V + 10 mV per °C. Tick “turn round” in the left column and place it the other way: +VS and GND swap and the sensor is connected backwards.' },
    { title: '✔ Servo motor', parts: [{ id: 'sv1', type: 'servo', row: 'j', col: 11 }, w('w1', 'GND2', 'i11', 'black'), w('w2', 'VIN', 'i12', 'red'), w('w3', 'G16', 'i13', 'orange')], pins: { G16: { mode: 'servo', angle: 45 } }, note: 'Servo plug: brown = GND, red = 5 V (the VIN pin, middle), orange = signal on GPIO16. The 3.3 V pulse is enough for the signal wire of an SG90 (a common setup, but not guaranteed for every servo). Move the angle slider. The code needs the ESP32Servo library.' },
    { title: '✖ Servo on 3.3 V', parts: [{ id: 'sv1', type: 'servo', row: 'j', col: 11 }, w('w1', 'GND2', 'i11', 'black'), w('w2', '3V3', 'i12', 'orange'), w('w3', 'G16', 'i13', 'orange')], pins: { G16: { mode: 'servo', angle: 45 } }, note: 'An SG90 servo needs 4.8–6 V. On 3.3 V it does not move (or only twitches). Use the VIN pin (5 V from USB).' },
    { title: '✖ HC-SR04 echo straight into a GPIO pin', parts: [{ id: 'us1', type: 'hcsr04', row: 'j', col: 11 }, w('w1', 'VIN', 'i11', 'red'), w('w2', 'G16', 'i12', 'yellow'), w('w3', 'G17', 'i13', 'blue'), w('w4', 'GND2', 'i14', 'black')], pins: { G16: { mode: 'pulse' }, G17: { mode: 'in' } }, note: 'The HC-SR04 runs on 5 V, so its ECHO output is 5 V, and ESP32 pins are 3.3 V only. This connection can damage the pin. Press “Replace broken parts”, then use the voltage divider example.' },
    { title: '✔ HC-SR04 with a voltage divider', parts: [{ id: 'us1', type: 'hcsr04', row: 'j', col: 11 }, w('w1', 'VIN', 'i11', 'red'), w('w2', 'G16', 'i12', 'yellow'), res('r1', 'h13', 'h17', 1000), res('r2', 'g17', 'g21', 2200), w('w3', 'G17', 'i17', 'blue'), w('w4', 'GND2', 'i14', 'black'), w('w5', 'GND1', 'i21', 'black')], pins: { G16: { mode: 'pulse' }, G17: { mode: 'in' } }, note: 'Two resistors (1 kΩ and 2.2 kΩ) divide the 5 V echo signal down to about 3.3 V, which is within the 3.6 V limit of an ESP32 pin. Drag the obstacle slider and watch the echo pulse change.' },
    { title: '✔ SHT31-D temperature and humidity (I²C)', parts: [{ id: 'sen1', type: 'sht31', row: 'g', col: 10 }, w('w1', '3V3', 'j10', 'red'), w('w2', 'GND2', 'j11', 'black'), w('w3', 'G22', 'j12', 'yellow'), w('w4', 'G21', 'j13', 'blue')], pins: { G22: { mode: 'i2c' }, G21: { mode: 'i2c' } }, note: 'Four wires: VIN to 3.3 V, GND, SCL (clock) to GPIO22 and SDA (data) to GPIO21, the default I²C pins of the Arduino core. The breakout has its own pull-up resistors. Change the temperature and humidity of the room on the right.' },
    { title: '✔ RGB LED (common cathode) with three resistors', parts: [{ id: 'rgb1', type: 'rgbled', row: 'e', col: 10 }, res('r1', 'a10', 'a16', 220), res('r2', 'a12', 'a17', 220), res('r3', 'a13', 'a18', 220), w('w1', 'G16', 'b16', 'red'), w('w2', 'G17', 'b17', 'green'), w('w3', 'G18', 'b18', 'blue'), w('w4', 'GND2', 'a11', 'black')], pins: { G16: { mode: 'pwm', duty: 0.8 }, G17: { mode: 'pwm', duty: 0.5 }, G18: { mode: 'pwm', duty: 0.1 } }, note: 'Red, green and blue legs each go through their own resistor to a PWM pin (ledcWrite), the longest (common) leg goes to GND. On a 3.3 V board the green and blue dice (about 3 V) get much less current than red, so they look dimmer.' },
    { title: '✖ RGB LED without resistors', parts: [{ id: 'rgb1', type: 'rgbled', row: 'e', col: 10 }, w('w1', 'G16', 'b10', 'red'), w('w2', 'G17', 'b12', 'green'), w('w3', 'G18', 'b13', 'blue'), w('w4', 'GND2', 'b11', 'black')], pins: { G16: { mode: 'out1' }, G17: { mode: 'out1' }, G18: { mode: 'out1' } }, note: 'The colour legs are wired straight to 3.3 V pins. Here only the small resistance inside the pin limits the current, and the red die already gets about 26 mA (its rating is about 20 mA). Never do this: add a resistor in each colour line.' },
    { title: '✔ DHT22 temperature and humidity', parts: [{ id: 'dht1', type: 'dht', model: 'dht22', row: 'e', col: 10 }, w('w1', '3V3', 'a10', 'red'), w('w2', 'G4', 'a11', 'yellow'), res('r1', 'c10', 'c16', 10000), w('w3', 'b11', 'b16', 'orange'), w('w4', 'GND2', 'a13', 'black')], pins: { G4: { mode: 'dht' } }, note: 'Pins from the left: VCC, DATA, (not connected), GND. VCC goes to 3V3 (never to VIN: the pulled-up DATA line would reach 5 V), DATA to GPIO4 set to “Single-wire data”, and a 10 kΩ pull-up resistor joins DATA and VCC. Change the room temperature and humidity on the right.' },
    { title: '✖ DHT22 powered from VIN (5 V)', parts: [{ id: 'dht1', type: 'dht', model: 'dht22', row: 'e', col: 10 }, w('w1', 'VIN', 'a10', 'red'), w('w2', 'G4', 'a11', 'yellow'), res('r1', 'c10', 'c16', 10000), w('w3', 'b11', 'b16', 'orange'), w('w4', 'GND2', 'a13', 'black')], pins: { G4: { mode: 'dht' } }, note: 'The sensor itself accepts 5 V, but the pull-up resistor goes to VCC, so the DATA line is pulled up to 5 V and GPIO4 sees 5 V. ESP32 pins are 3.3 V only: power the sensor from 3V3.' },
    { title: '✔ Joystick module (two analog axes + switch)', parts: [{ id: 'joy1', type: 'joystick', row: 'g', col: 10 }, w('w1', 'GND2', 'j10', 'black'), w('w2', '3V3', 'j11', 'red'), w('w3', 'G34', 'j12', 'green'), w('w4', 'G35', 'j13', 'blue'), w('w5', 'G17', 'j14', 'yellow')], pins: { G34: { mode: 'analog' }, G35: { mode: 'analog' }, G17: { mode: 'up' } }, note: 'VRx goes to GPIO34 and VRy to GPIO35 (ADC1 inputs, 12-bit: 0 … 4095), SW to GPIO17 with the pull-up. The module is powered from 3V3. Move the stick with the sliders on the right: at the centre each axis reads about 2048.' },
    { title: '✖ Joystick powered from VIN (5 V)', parts: [{ id: 'joy1', type: 'joystick', row: 'g', col: 10 }, w('w1', 'GND2', 'j10', 'black'), w('w2', 'VIN', 'j11', 'red'), w('w3', 'G34', 'j12', 'green'), w('w4', 'G35', 'j13', 'blue')], pins: { G34: { mode: 'analog' }, G35: { mode: 'analog' } }, note: 'On 5 V the stick outputs go up to 5 V, but ESP32 pins are 3.3 V only: a stick pushed to the right (X slider) or down (Y slider) can damage GPIO34 and GPIO35. Power the module from 3V3.' },
    { title: '✔ Rotary encoder (CLK, DT, SW with pull-ups)', parts: [{ id: 'enc1', type: 'encoder', row: 'g', col: 10 }, w('w1', 'G16', 'j10', 'green'), w('w2', 'G17', 'j11', 'blue'), w('w3', 'G18', 'j12', 'yellow'), w('w4', '3V3', 'j13', 'red'), w('w5', 'GND2', 'j14', 'black')], pins: { G16: { mode: 'up' }, G17: { mode: 'up' }, G18: { mode: 'up' } }, note: 'The knob closes CLK and DT to GND in a shifted pattern. Use “step ▶” and “◀ step” on the right and watch the two pins change one after the other. The pins use the internal pull-up (about 45 kΩ).' },
    { title: '✔ NeoPixel strip (8 pixels) on one data pin', parts: neoE32('VIN', 'G16', 'GND2'), pins: { G16: { mode: 'neopixel', pattern: 'rainbow', bright: 40 } }, note: 'The strip is powered from VIN (5 V from USB) with the data line on GPIO16. The ESP32 pin gives only 3.3 V, below the 3.5 V (70 % of 5 V) the pixels want on DIN: see the next example.' },
    { title: '✖ 5 V NeoPixels with a 3.3 V data pin', parts: neoE32('VIN', 'G16', 'GND2'), pins: { G16: { mode: 'neopixel', pattern: 'rainbow', bright: 40 } }, note: 'The strip runs at 5 V, so its data input needs at least 70 % of that, 3.5 V (Adafruit). A 3.3 V pin is just below it, so the pixels may show wrong colours or nothing. Fix: a level shifter between the pin and DIN, or a lower strip supply voltage.' },
    { title: '✔ LCD 16×2 with I²C backpack', parts: i2cDispE('lcd1602', 'lcd1', 'VIN', 'G21', 'G22'), pins: { G21: { mode: 'i2c' }, G22: { mode: 'i2c' } }, note: 'The LCD is powered from VIN (5 V) and read on GPIO21 (SDA) and GPIO22 (SCL). Many backpacks pull SDA and SCL up to VCC, which would put 5 V on these 3.3 V pins: check your module or use a level shifter. The text comes from the two lines on the right.' },
    { title: '✔ OLED 128×64 (SSD1306, I²C)', parts: i2cDispE('oled', 'oled1', '3V3', 'G21', 'G22'), pins: { G21: { mode: 'i2c' }, G22: { mode: 'i2c' } }, note: 'GND, VCC (3V3), SCL (GPIO22) and SDA (GPIO21). The display answers at address 0x3C (0x3D on some modules).' },
    { title: '✔ Transistor switches a 6 V lamp', parts: qLampE('G16', 470, false), pins: { G16: { mode: 'out1' } }, note: 'GPIO16 cannot drive a lamp that needs about 300 mA. It drives the BASE of a PN2222A through a 470 Ω resistor (about 5 mA); the transistor lets the lamp’s current flow from the 6 V pack through the collector to the emitter and GND. The battery − and the board GND are joined at the emitter column.' },
    { title: '✖ Transistor without a base resistor', parts: qLampE('G16', 0, false), pins: { G16: { mode: 'out1' } }, note: 'The base is wired straight to GPIO16. Nothing limits the current into the base-emitter junction: the pin has to deliver far more than it can and is damaged. Put a resistor in the base line.' },
    { title: '⚠ MOSFET switches a motor from a 3.3 V pin', parts: mosParts('G16', 'GND2', ldE, { motor: true, diode: true }), pins: { G16: { mode: 'out1' } }, note: 'The motor takes about 1 A. The IRLZ44N datasheet guarantees its on-resistance only for a gate voltage of 4 V and above (35 mΩ at 4 V) and gives no value at 3.3 V, so the app warns. Many real parts do switch at 3.3 V, but it is not guaranteed: for a motor use a 5 V gate drive or a gate driver.' },
    { title: '✔ MOSFET switches a 6 V lamp', parts: mosParts('G16', 'GND2', ldE), pins: { G16: { mode: 'out1' } }, note: 'GPIO16 drives the GATE of an IRLZ44N through 220 Ω. The gate takes no steady current: only its voltage matters. The lamp current flows from the 6 V pack through the drain and source to GND. The 10 kΩ resistor from gate to GND keeps it OFF while the pin is not yet an output.' },
    { title: '✖ MOSFET motor without a flyback diode', parts: mosParts('G16', 'GND2', ldE, { motor: true }), pins: { G16: { mode: 'out1' } }, note: 'When the motor is switched off, its coil keeps pushing current and makes a voltage spike far above the supply. Without a diode across the motor, the spike can destroy the MOSFET.' },
    { title: '✖ MOSFET gate not connected', parts: mosParts('G16', 'GND2', ldE, { nogate: true }), pins: {}, note: 'The gate is left floating. A MOSFET gate holds charge and can switch the load on or off by itself. Always drive the gate from a pin and add a resistor from gate to GND.' },
    { title: '✖ MOSFET drain and source swapped', parts: mosParts('G16', 'GND2', ldE, { swap: true }), pins: { G16: { mode: 'out1' } }, note: 'The load is on the source leg and GND on the drain leg. The built-in body diode now conducts, so the lamp is on whatever the gate does. The TO-220 pins are gate, drain, source from left to right (text toward you).' },
    { title: '✔ Capacitor charges slowly: the LED fades in', parts: rcParts('G16', 'GND2'), pins: { G16: { mode: 'out1' } }, note: 'The pin charges a 470 µF capacitor through 1 kΩ: τ = R × C = 0.47 s, so the voltage across the capacitor (and the LED brightness) rises gradually. After about 5 τ it is full.' },
    { title: '✔ Capacitor keeps the LED glowing after the pin goes LOW', parts: rcParts('G16', 'GND2'), caps: { cap1: 3.4 }, pins: { G16: { mode: 'out0' } }, note: 'The capacitor starts charged (3.4 V). With the pin LOW it discharges through the LED branch and through the 1 kΩ resistor to the pin, so the LED fades out over a fraction of a second instead of switching off at once.' },
    { title: '✖ Capacitor connected backwards', parts: rcParts('G16', 'GND2', { rev: true }), pins: { G16: { mode: 'out1' } }, note: 'The + leg is toward GND and the stripe (−) toward the resistor. An electrolytic capacitor is polarised: with voltage the wrong way round it fails (in real life it can vent or burst).' },
    { title: '✖ Capacitor straight from a pin (no resistor)', parts: rcParts('G16', 'GND2', { noR: true }), pins: { G16: { mode: 'out1' } }, note: 'An empty capacitor acts like a short circuit for a moment: with nothing to limit the inrush current, the pin has to deliver far more than it can and is damaged. Always charge through a resistor.' },
    { title: '✖ EN pin wired to GND (chip held in reset)', parts: [...ledCircuit(false), w('w3', 'EN', 'a20', 'yellow'), w('w4', 'GND1', 'b20', 'black')], pins: { G16: { mode: 'out1' } }, note: 'GPIO16 is set to Output HIGH and the LED circuit is correct, but the EN pin is joined to GND. EN is the chip-enable (reset) input: while it is LOW the ESP32 does not run, so no pin is driven and the LED stays dark. This is what the EN button does while you hold it. Delete the EN wire and the LED lights.' },
    { title: '✖ 5 V on a 3.3 V pin', parts: [w('w1', 'VIN', 'a10', 'red'), w('w2', 'G17', 'b10', 'yellow')], pins: { G17: { mode: 'in' } }, note: 'VIN carries the 5 V from USB. ESP32 pins are 3.3 V only (3.6 V at most), so 5 V on a GPIO pin can damage the chip. Press “Replace broken parts”.' },
    { title: '✖ LED without a resistor', parts: [w('w1', 'VIN', 'a10', 'red'), led('led1', 'c10', 'c11'), w('w2', 'GND2', 'd11', 'black')], pins: {}, note: 'The LED is connected straight to the 5 V pin with no resistor. Nothing limits the current, so it burns out in a moment. Press “Replace broken parts”, then put a resistor in the path.' },
  ];
}
